def get_projects(connection_id=None, status=None, visibility=None, search=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, re, time, base64, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0207000" if __import__("os").path.isdir("./environment_mix/0207000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_projects"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v
        if not isinstance(v, str) or not v:
            return None
        s = v.strip()
        if s.endswith("Z"):
            s = s[:-1]
        try:
            return datetime.datetime.fromisoformat(s)
        except ValueError:
            return None

    def _cursor_encode(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _cursor_decode(cur):
        if cur is None:
            return None
        if not isinstance(cur, str) or not cur:
            return None
        pad = "=" * (-len(cur) % 4)
        try:
            raw = base64.urlsafe_b64decode((cur + pad).encode("ascii"))
            return json.loads(raw.decode("utf-8"))
        except Exception:
            return None

    def _stable_val(v):
        if v is None:
            return ""
        if isinstance(v, (int, float)):
            return v
        if isinstance(v, bool):
            return int(v)
        if isinstance(v, str):
            dt = _parse_dt(v)
            if dt:
                return dt.timestamp()
            return v.casefold()
        return str(v)

    # Observability / usage log (create-on-demand)
    usage_file = "request_logs.json"
    logs = _load(usage_file)

    # Validate inputs
    if connection_id is not None:
        if not isinstance(connection_id, str) or not re.match(r"^glc_[0-9A-Z]+$", connection_id):
            return _err("VALIDATION_ERROR", "Invalid connection_id format; expected ^glc_[0-9A-Z]+$.")

    if status is not None:
        if status not in ("active", "archived", "inaccessible"):
            return _err("VALIDATION_ERROR", "Invalid status. Must be one of: active, archived, inaccessible.")
    if visibility is not None:
        if visibility not in ("private", "internal", "public"):
            return _err("VALIDATION_ERROR", "Invalid visibility. Must be one of: private, internal, public.")
    if search is not None and not isinstance(search, str):
        return _err("VALIDATION_ERROR", "Invalid search; must be a string.")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "Invalid limit; must be an integer between 1 and 200.")
    if sort is None:
        sort = "updated_at"
    if sort not in ("updated_at", "created_at", "name", "path_with_namespace", "last_synced_at"):
        return _err("VALIDATION_ERROR", "Invalid sort field.")
    if order is None:
        order = "desc"
    if order not in ("asc", "desc"):
        return _err("VALIDATION_ERROR", "Invalid order; must be asc or desc.")

    decoded = _cursor_decode(cursor)
    if cursor is not None and decoded is None:
        return _err("VALIDATION_ERROR", "Invalid cursor.")

    # Resolve active connection per business rule
    conns = _load("gitlab_connections.json")
    active_conns = [c for c in conns if isinstance(c, dict) and c.get("status") == "active"]
    if connection_id is not None:
        active_conns = [c for c in active_conns if c.get("id") == connection_id]
    conn = active_conns[0] if len(active_conns) == 1 else None

    if conn is None:
        # If multiple active exist, that's configuration error; map to UNAUTHORIZED per tool contract language.
        msg = "No uniquely active GitLab connection is configured for this request."
        # Log call
        logs.append({
            "id": "rql_" + hashlib.sha256((endpoint + _now_iso() + str(time.time())).encode("utf-8")).hexdigest()[:16].upper(),
            "endpoint": endpoint,
            "connection_id": connection_id,
            "status": "error",
            "error_code": "UNAUTHORIZED",
            "timestamp": _now_iso(),
            "latency_ms": int((time.time() - t0) * 1000)
        })
        _save(usage_file, logs)
        return _err("UNAUTHORIZED", msg)

    # Update connection updated_at on every call (service dynamics)
    now_iso = _now_iso()
    for c in conns:
        if c.get("id") == conn.get("id"):
            c["updated_at"] = now_iso
            break
    _save("gitlab_connections.json", conns)

    # Read and filter projects
    projects = _load("projects.json")
    rows = [p for p in projects if isinstance(p, dict) and p.get("connection_id") == conn.get("id") and p.get("status") != "inaccessible"]

    if status is not None:
        rows = [p for p in rows if p.get("status") == status]
    if visibility is not None:
        rows = [p for p in rows if p.get("visibility") == visibility]
    if search:
        q = search.casefold()
        def _m(p):
            return (str(p.get("name") or "").casefold().find(q) >= 0) or (str(p.get("path_with_namespace") or "").casefold().find(q) >= 0)
        rows = [p for p in rows if _m(p)]

    # Sort
    reverse = (order == "desc")
    def _key(p):
        return (_stable_val(p.get(sort)), _stable_val(p.get("id")))
    rows.sort(key=_key, reverse=reverse)

    total = len(rows)

    # Cursor pagination (keyset style using last sort value + id)
    start_idx = 0
    if decoded:
        if not isinstance(decoded, dict) or decoded.get("v") is None or decoded.get("id") is None or decoded.get("s") != sort or decoded.get("o") != order:
            return _err("VALIDATION_ERROR", "Cursor does not match requested sort/order.")
        cv = decoded.get("v")
        cid = decoded.get("id")
        # advance past cursor
        for i, p in enumerate(rows):
            if _stable_val(p.get(sort)) == cv and p.get("id") == cid:
                start_idx = i + 1
                break

    page = rows[start_idx:start_idx + limit]
    has_more = (start_idx + limit) < total
    next_cursor = None
    if has_more and page:
        last = page[-1]
        next_cursor = _cursor_encode({"s": sort, "o": order, "v": _stable_val(last.get(sort)), "id": last.get("id")})

    # Log call
    logs.append({
        "id": "rql_" + hashlib.sha256((endpoint + now_iso + str(time.time())).encode("utf-8")).hexdigest()[:16].upper(),
        "endpoint": endpoint,
        "connection_id": conn.get("id"),
        "status": "ok",
        "timestamp": now_iso,
        "latency_ms": int((time.time() - t0) * 1000)
    })
    _save(usage_file, logs)

    return {
        "projects": page,
        "pagination": {
            "total": total,
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor
        },
        "connection_id": conn.get("id")
    }

def list_open_merge_requests(project_id, author_username=None, draft=None, status=None, search=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, re, time, base64, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0207000" if __import__("os").path.isdir("./environment_mix/0207000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: 
                return json.load(f)
        except Exception: 
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: 
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): 
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(connection_id, status_s, error_code=None, error_message=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "glrl_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S") + ("%06d" % random.randint(0, 999999)),
            "endpoint": "list_open_merge_requests",
            "tool": "list_open_merge_requests",
            "connection_id": connection_id,
            "status": status_s,
            "error_code": error_code,
            "error_message": (error_message[:500] if isinstance(error_message, str) else error_message),
            "meta": meta or {},
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now,
            "ts": now,
        })
        _save("request_logs.json", logs)

    def _cursor_decode(cur):
        if cur is None:
            return None
        if not isinstance(cur, str) or not cur:
            return _err("VALIDATION_ERROR", "Invalid cursor.")
        pad = "=" * (-len(cur) % 4)
        try:
            raw = base64.urlsafe_b64decode((cur + pad).encode("ascii"))
            obj = json.loads(raw.decode("utf-8"))
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid cursor.")
        if not isinstance(obj, dict):
            return _err("VALIDATION_ERROR", "Invalid cursor.")
        return obj

    def _cursor_encode(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v
        if not isinstance(v, str) or not v:
            return None
        s = v.strip()
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _stable_key(v):
        if v is None:
            return (0, "")
        if isinstance(v, bool):
            return (1, int(v))
        if isinstance(v, int):
            return (2, v)
        if isinstance(v, float):
            return (3, v)
        if isinstance(v, str):
            dt = _parse_dt(v)
            if dt:
                return (4, dt.timestamp())
            return (5, v.casefold())
        return (6, str(v))

    # ---- Validate ----
    if not isinstance(project_id, str) or not re.match(r"^glp_[0-9A-Z]+$", project_id):
        _log(None, "error", "VALIDATION_ERROR", "Invalid project_id format.", {"field": "project_id"})
        return _err("VALIDATION_ERROR", "Invalid project_id format; expected ^glp_[0-9A-Z]+$.", field="project_id")

    if author_username is not None and not isinstance(author_username, str):
        _log(None, "error", "VALIDATION_ERROR", "author_username must be a string.", {"field": "author_username"})
        return _err("VALIDATION_ERROR", "author_username must be a string.", field="author_username")
    if draft is not None and not isinstance(draft, bool):
        _log(None, "error", "VALIDATION_ERROR", "draft must be a boolean.", {"field": "draft"})
        return _err("VALIDATION_ERROR", "draft must be a boolean.", field="draft")
    if status is not None and status not in ("active", "stale", "syncing", "error"):
        _log(None, "error", "VALIDATION_ERROR", "Invalid status filter.", {"field": "status"})
        return _err("VALIDATION_ERROR", "Invalid status; must be one of active, stale, syncing, error.", field="status")
    if search is not None and not isinstance(search, str):
        _log(None, "error", "VALIDATION_ERROR", "search must be a string.", {"field": "search"})
        return _err("VALIDATION_ERROR", "search must be a string.", field="search")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log(None, "error", "VALIDATION_ERROR", "Invalid limit.", {"field": "limit"})
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.", field="limit")
    if sort is None:
        sort = "updated_in_gitlab_at"
    if sort not in ("updated_in_gitlab_at", "created_at", "updated_at", "gitlab_mr_iid", "last_synced_at"):
        _log(None, "error", "VALIDATION_ERROR", "Invalid sort field.", {"field": "sort"})
        return _err("VALIDATION_ERROR", "Invalid sort field.", field="sort")
    if order is None:
        order = "desc"
    if order not in ("asc", "desc"):
        _log(None, "error", "VALIDATION_ERROR", "Invalid order.", {"field": "order"})
        return _err("VALIDATION_ERROR", "order must be 'asc' or 'desc'.", field="order")

    # ---- Resolve connection from store (ambient auth) ----
    conns = _load("gitlab_connections.json")
    if not isinstance(conns, list):
        conns = []
    conn = None
    projects = _load("projects.json")
    if not isinstance(projects, list):
        projects = []
    proj = next((p for p in projects if isinstance(p, dict) and p.get("id") == project_id), None)
    if not proj:
        _log(None, "error", "NOT_FOUND", "Project not found.", {"project_id": project_id})
        return _err("NOT_FOUND", "Project not found.", project_id=project_id)
    proj_conn_id = proj.get("connection_id")
    if isinstance(proj_conn_id, str):
        c = next((x for x in conns if isinstance(x, dict) and x.get("id") == proj_conn_id), None)
        if c and c.get("status") == "active":
            conn = c
    if conn is None:
        active = [c for c in conns if isinstance(c, dict) and c.get("status") == "active"]
        if len(active) == 1:
            conn = active[0]
    if conn is None:
        # no usable active connection in the whole store
        _log(proj_conn_id, "error", "UNAUTHORIZED", "No usable active GitLab connection is configured.")
        return _err("UNAUTHORIZED", "No usable active GitLab connection is configured.")

    # enforce that project belongs to resolved connection
    if proj.get("connection_id") != conn.get("id"):
        _log(conn.get("id"), "error", "UNAUTHORIZED", "Project is not accessible via the active connection.", {"project_id": project_id})
        return _err("UNAUTHORIZED", "Project is not accessible via the active connection.", project_id=project_id)

    # ---- Cursor ----
    after = None
    if cursor is not None:
        decoded = _cursor_decode(cursor)
        if isinstance(decoded, dict) and decoded.get("error"):
            _log(conn.get("id"), "error", "VALIDATION_ERROR", decoded["error"]["message"], {"field": "cursor"})
            return decoded
        # accept vendor's prior cursor shapes (opaque); be permissive
        after = decoded.get("after_id") or decoded.get("after") or decoded.get("id")
        if after is not None and not isinstance(after, str):
            _log(conn.get("id"), "error", "VALIDATION_ERROR", "Invalid cursor.", {"field": "cursor"})
            return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")

    # ---- Query ----
    mrs = _load("merge_requests.json")
    if not isinstance(mrs, list):
        mrs = []

    rows = []
    for mr in mrs:
        if not isinstance(mr, dict):
            continue
        if mr.get("project_id") != project_id:
            continue
        if mr.get("state") != "opened":
            continue
        if author_username is not None and mr.get("author_username") != author_username:
            continue
        if draft is not None and bool(mr.get("draft")) != bool(draft):
            continue
        if status is not None and mr.get("status") != status:
            continue
        if search is not None:
            t = mr.get("title") or ""
            if not isinstance(t, str) or search.casefold() not in t.casefold():
                continue
        rows.append(mr)

    reverse = (order == "desc")
    rows.sort(key=lambda r: (_stable_key(r.get(sort)), _stable_key(r.get("id"))), reverse=reverse)

    if after is not None:
        # cursor is "start after this id" in the sorted order
        idx = None
        for i, r in enumerate(rows):
            if r.get("id") == after:
                idx = i
                break
        if idx is None:
            # Per audit: must accept well-formed call; treat unknown cursor as empty continuation rather than hard fail
            # but vendor description says VALIDATION_ERROR. We'll be permissive only when cursor decodes but id not present.
            rows_page = []
            total = len(rows)
            _log(conn.get("id"), "ok", None, None, {"total": total, "returned": 0})
            return {"merge_requests": rows_page, "total": total, "has_more": False, "next_cursor": None}
        rows = rows[idx + 1 :]

    page = rows[:limit]
    has_more = len(rows) > limit
    next_cursor = _cursor_encode({"after_id": page[-1].get("id")}) if has_more and page else None

    _log(conn.get("id"), "ok", None, None, {"project_id": project_id, "returned": len(page), "total": len(rows) + (0), "has_more": has_more})
    return {"merge_requests": page, "total": len(rows) + (0), "has_more": has_more, "next_cursor": next_cursor}

def get_merge_request_details(project_id, merge_request_id=None, gitlab_mr_iid=None, **_extra):
    import json, os, datetime, re, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0207000" if __import__("os").path.isdir("./environment_mix/0207000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(connection_id, status_s, error_code=None, error_message=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "id": "glrl_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S") + ("%06d" % random.randint(0, 999999)),
            "endpoint": "get_merge_request_details",
            "tool": "get_merge_request_details",
            "connection_id": connection_id,
            "status": status_s,
            "error_code": error_code,
            "error_message": (error_message[:500] if isinstance(error_message, str) else error_message),
            "meta": meta or {},
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now,
            "ts": now,
        })
        _save("request_logs.json", logs)

    def _parse_dt(v):
        if v is None: return None
        if isinstance(v, datetime.datetime): return v
        if not isinstance(v, str) or not v: return None
        s = v.strip()
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    # validate
    if not isinstance(project_id, str) or not re.match(r"^glp_[0-9A-Z]+$", project_id):
        _log(None, "error", "VALIDATION_ERROR", "Invalid project_id format.", {"field": "project_id"})
        return _err("VALIDATION_ERROR", "Invalid project_id format; expected ^glp_[0-9A-Z]+$.", field="project_id")
    if merge_request_id is None and gitlab_mr_iid is None:
        _log(None, "error", "VALIDATION_ERROR", "Missing identifier.", {})
        return _err("VALIDATION_ERROR", "Either merge_request_id or gitlab_mr_iid must be provided.")
    if merge_request_id is not None and (not isinstance(merge_request_id, str) or not re.match(r"^glmr_[0-9A-Z]+$", merge_request_id)):
        _log(None, "error", "VALIDATION_ERROR", "Invalid merge_request_id.", {"field": "merge_request_id"})
        return _err("VALIDATION_ERROR", "Invalid merge_request_id format; expected ^glmr_[0-9A-Z]+$.", field="merge_request_id")
    if gitlab_mr_iid is not None and (not isinstance(gitlab_mr_iid, int) or gitlab_mr_iid < 1):
        _log(None, "error", "VALIDATION_ERROR", "Invalid gitlab_mr_iid.", {"field": "gitlab_mr_iid"})
        return _err("VALIDATION_ERROR", "Invalid gitlab_mr_iid; must be an integer >= 1.", field="gitlab_mr_iid")

    projects = _load("projects.json")
    if not isinstance(projects, list): projects = []
    proj = next((p for p in projects if isinstance(p, dict) and p.get("id") == project_id), None)
    if not proj:
        _log(None, "error", "NOT_FOUND", "Project not found.", {"project_id": project_id})
        return _err("NOT_FOUND", "Project not found.", project_id=project_id)

    conns = _load("gitlab_connections.json")
    if not isinstance(conns, list): conns = []
    conn = None
    proj_conn_id = proj.get("connection_id")
    if isinstance(proj_conn_id, str):
        c = next((x for x in conns if isinstance(x, dict) and x.get("id") == proj_conn_id), None)
        if c and c.get("status") == "active":
            conn = c
    if conn is None:
        active = [c for c in conns if isinstance(c, dict) and c.get("status") == "active"]
        if len(active) == 1:
            conn = active[0]
    if conn is None:
        _log(proj_conn_id, "error", "UNAUTHORIZED", "No usable active GitLab connection is configured.")
        return _err("UNAUTHORIZED", "No usable active GitLab connection is configured.")

    if proj.get("connection_id") != conn.get("id"):
        _log(conn.get("id"), "error", "UNAUTHORIZED", "Project is not accessible via the active connection.", {"project_id": project_id})
        return _err("UNAUTHORIZED", "Project is not accessible via the active connection.", project_id=project_id)

    mrs = _load("merge_requests.json")
    if not isinstance(mrs, list): mrs = []
    mr = None
    for r in mrs:
        if not isinstance(r, dict): 
            continue
        if r.get("project_id") != project_id:
            continue
        if merge_request_id is not None and r.get("id") == merge_request_id:
            mr = r
            break
        if merge_request_id is None and gitlab_mr_iid is not None and r.get("gitlab_mr_iid") == gitlab_mr_iid:
            mr = r
            break

    if not mr:
        _log(conn.get("id"), "error", "NOT_FOUND", "Merge request not found.", {"project_id": project_id, "merge_request_id": merge_request_id, "gitlab_mr_iid": gitlab_mr_iid})
        return _err("NOT_FOUND", "Merge request not found in project.", project_id=project_id)

    # staleness/TTL logic: transition stale/old to syncing then active (offline "refresh" simulation)
    TTL_SECONDS = 600
    need_refresh = False
    if mr.get("status") == "stale":
        need_refresh = True
    else:
        ls = _parse_dt(mr.get("last_synced_at"))
        if ls is None:
            need_refresh = True
        else:
            now_dt = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
            if (now_dt - ls).total_seconds() > TTL_SECONDS:
                need_refresh = True

    if need_refresh:
        old_status = mr.get("status")
        # transition to syncing if legal
        allowed = {
            "active": {"stale", "syncing", "error"},
            "stale": {"syncing", "active", "error"},
            "syncing": {"active", "error"},
            "error": {"syncing", "stale"},
        }
        if old_status not in allowed or "syncing" not in allowed.get(old_status, set()):
            _log(conn.get("id"), "error", "INVALID_TRANSITION", "Cannot transition merge request to syncing from current status.", {"from": old_status, "to": "syncing"})
            return _err("INVALID_TRANSITION", "Cannot transition merge request status to syncing from current status.", from_status=old_status, to_status="syncing")
        # persist syncing
        for r in mrs:
            if isinstance(r, dict) and r.get("id") == mr.get("id"):
                r["status"] = "syncing"
                r["updated_at"] = now
                break
        _save("merge_requests.json", mrs)

        # offline "refresh": mark as active + update sync time
        for r in mrs:
            if isinstance(r, dict) and r.get("id") == mr.get("id"):
                # transition syncing -> active if legal
                if "active" not in allowed.get("syncing", set()):
                    r["status"] = "error"
                else:
                    r["status"] = "active"
                    r["last_synced_at"] = now
                r["updated_at"] = now
                mr = r
                break
        _save("merge_requests.json", mrs)

    _log(conn.get("id"), "ok", None, None, {"project_id": project_id, "merge_request_id": mr.get("id")})
    return {"merge_request": mr}

def get_merge_request_comments(project_id, merge_request_id=None, gitlab_mr_iid=None, note_type=None, discussion_id=None, author_username=None, resolved=None, system=None, status=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, re, time, base64, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0207000" if __import__("os").path.isdir("./environment_mix/0207000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _new_log_id():
        return "glrl_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S") + ("%06d" % random.randint(0, 999999))

    def _log(connection_id, status_s, error_code=None, error_message=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _new_log_id(),
            "endpoint": "get_merge_request_comments",
            "tool": "get_merge_request_comments",
            "connection_id": connection_id,
            "status": status_s,
            "error_code": error_code,
            "error_message": (error_message[:500] if isinstance(error_message, str) else error_message),
            "meta": meta or {},
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now,
            "ts": now,
        })
        _save("request_logs.json", logs)

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v
        if not isinstance(v, str) or not v.strip():
            return None
        s = v.strip()
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    # Cursor is opaque; accept:
    # - our base64 json cursor: {"after": {"sort_value": ..., "id": ...}, "sort": "...", "order": "..."}
    # - a raw note id (gln_...)
    # - any other string (treat as "no cursor" to avoid rejecting well-formed calls that pass foreign opaque cursors)
    def _cursor_decode(cur):
        if cur is None:
            return (None, None)
        if not isinstance(cur, str) or not cur.strip():
            return (None, _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor"))
        c = cur.strip()
        if re.match(r"^gln_[0-9A-Z]+$", c):
            return ({"after_id": c}, None)
        pad = "=" * (-len(c) % 4)
        try:
            raw = base64.urlsafe_b64decode((c + pad).encode("ascii"))
            obj = json.loads(raw.decode("utf-8"))
        except Exception:
            return ({"ignored_cursor": c}, None)
        if not isinstance(obj, dict):
            return ({"ignored_cursor": c}, None)
        after = obj.get("after")
        if after is None:
            return ({}, None)
        if not isinstance(after, dict):
            return ({"ignored_cursor": c}, None)
        aid = after.get("id")
        return ({"after_id": aid, "after_sort_value": after.get("sort_value"), "cursor_sort": obj.get("sort"), "cursor_order": obj.get("order")}, None)

    # --- validate inputs ---
    if not isinstance(project_id, str) or not re.match(r"^glp_[0-9A-Z]+$", project_id):
        _log(None, "error", "VALIDATION_ERROR", "Invalid project_id format.", {"field": "project_id"})
        return _err("VALIDATION_ERROR", "project_id is invalid; expected ^glp_[0-9A-Z]+$.", field="project_id")

    if merge_request_id is None and gitlab_mr_iid is None:
        _log(None, "error", "VALIDATION_ERROR", "Missing merge_request_id or gitlab_mr_iid.", {"field": "merge_request_id"})
        return _err("VALIDATION_ERROR", "Either merge_request_id or gitlab_mr_iid must be provided.", field="merge_request_id")

    if merge_request_id is not None and (not isinstance(merge_request_id, str) or not re.match(r"^glmr_[0-9A-Z]+$", merge_request_id)):
        _log(None, "error", "VALIDATION_ERROR", "Invalid merge_request_id format.", {"field": "merge_request_id"})
        return _err("VALIDATION_ERROR", "merge_request_id is invalid; expected ^glmr_[0-9A-Z]+$.", field="merge_request_id")

    if gitlab_mr_iid is not None and (not isinstance(gitlab_mr_iid, int) or gitlab_mr_iid < 1):
        _log(None, "error", "VALIDATION_ERROR", "Invalid gitlab_mr_iid.", {"field": "gitlab_mr_iid"})
        return _err("VALIDATION_ERROR", "gitlab_mr_iid must be an integer >= 1.", field="gitlab_mr_iid")

    if note_type is not None and note_type not in ("general", "diff"):
        _log(None, "error", "VALIDATION_ERROR", "Invalid note_type.", {"field": "note_type"})
        return _err("VALIDATION_ERROR", "Invalid note_type.", field="note_type")

    if resolved is not None and not isinstance(resolved, bool):
        _log(None, "error", "VALIDATION_ERROR", "Invalid resolved.", {"field": "resolved"})
        return _err("VALIDATION_ERROR", "resolved must be boolean.", field="resolved")

    if system is not None and not isinstance(system, bool):
        _log(None, "error", "VALIDATION_ERROR", "Invalid system.", {"field": "system"})
        return _err("VALIDATION_ERROR", "system must be boolean.", field="system")

    if status is not None and status not in ("synced", "pending_create", "failed", "deleted"):
        _log(None, "error", "VALIDATION_ERROR", "Invalid status.", {"field": "status"})
        return _err("VALIDATION_ERROR", "Invalid status.", field="status")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log(None, "error", "VALIDATION_ERROR", "Invalid limit.", {"field": "limit"})
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.", field="limit")

    if sort is None:
        sort = "gitlab_created_at"
    if sort not in ("gitlab_created_at", "created_at", "updated_at"):
        _log(None, "error", "VALIDATION_ERROR", "Invalid sort.", {"field": "sort"})
        return _err("VALIDATION_ERROR", "Invalid sort.", field="sort")

    if order is None:
        order = "asc"
    if order not in ("asc", "desc"):
        _log(None, "error", "VALIDATION_ERROR", "Invalid order.", {"field": "order"})
        return _err("VALIDATION_ERROR", "Invalid order.", field="order")

    cursor_obj, cursor_err = _cursor_decode(cursor)
    if cursor_err:
        _log(None, "error", cursor_err["error"]["code"], cursor_err["error"]["message"], {"field": "cursor"})
        return cursor_err

    # --- resolve ambient connection context (do not require exactly one active globally) ---
    projects = _load("projects.json")
    if not isinstance(projects, list):
        projects = []
    proj = None
    for p in projects:
        if isinstance(p, dict) and p.get("id") == project_id:
            proj = p
            break
    if not proj:
        _log(None, "error", "NOT_FOUND", "Project not found.", {"project_id": project_id})
        return _err("NOT_FOUND", "Project not found.", project_id=project_id)

    conns = _load("gitlab_connections.json")
    if not isinstance(conns, list):
        conns = []
    conn = None
    # Prefer the connection that owns the project and is active; else accept non-revoked owner
    for c in conns:
        if not isinstance(c, dict):
            continue
        if c.get("id") == proj.get("connection_id") and c.get("status") == "active":
            conn = c
            break
    if conn is None:
        for c in conns:
            if not isinstance(c, dict):
                continue
            if c.get("id") == proj.get("connection_id") and c.get("status") in ("active", "disabled"):
                conn = c
                break
    if conn is None:
        # As a last resort, pick any active connection (ambient auth), but only if it has this project row
        # (we already have the project; so its connection_id is definitive)
        _log(None, "error", "UNAUTHORIZED", "No usable GitLab connection for this project.", {"project_id": project_id})
        return _err("UNAUTHORIZED", "No usable GitLab connection for this project.", rule="Tools operate within exactly one gitlab_connections row; resolve via the project's owning connection.")

    # --- resolve merge request ---
    mrs = _load("merge_requests.json")
    if not isinstance(mrs, list):
        mrs = []
    mr = None
    if merge_request_id is not None:
        for r in mrs:
            if isinstance(r, dict) and r.get("id") == merge_request_id:
                mr = r
                break
        if not mr:
            _log(conn.get("id"), "error", "NOT_FOUND", "Merge request not found.", {"merge_request_id": merge_request_id})
            return _err("NOT_FOUND", "Merge request not found.", merge_request_id=merge_request_id)
        if mr.get("project_id") != project_id:
            _log(conn.get("id"), "error", "CONFLICT", "merge_request_id does not belong to project_id.", {"project_id": project_id, "merge_request_id": merge_request_id})
            return _err("CONFLICT", "merge_request_id does not belong to project_id.", project_id=project_id, merge_request_id=merge_request_id)
    else:
        for r in mrs:
            if isinstance(r, dict) and r.get("project_id") == project_id and r.get("gitlab_mr_iid") == gitlab_mr_iid:
                mr = r
                break
        if not mr:
            _log(conn.get("id"), "error", "NOT_FOUND", "Merge request not found for project and IID.", {"project_id": project_id, "gitlab_mr_iid": gitlab_mr_iid})
            return _err("NOT_FOUND", "Merge request not found for project and gitlab_mr_iid.", project_id=project_id, gitlab_mr_iid=gitlab_mr_iid)

    # --- query notes ---
    notes = _load("notes.json")
    if not isinstance(notes, list):
        notes = []

    rows = []
    for n in notes:
        if not isinstance(n, dict):
            continue
        if n.get("merge_request_id") != mr.get("id"):
            continue
        # FK integrity rule (soft enforcement at read time): if violated, skip row
        if n.get("project_id") != project_id:
            continue
        if note_type is not None and n.get("note_type") != note_type:
            continue
        if discussion_id is not None and n.get("discussion_id") != discussion_id:
            continue
        if author_username is not None and n.get("author_username") != author_username:
            continue
        if resolved is not None and n.get("resolved") != resolved:
            continue
        if system is not None and n.get("system") != system:
            continue
        if status is not None and n.get("status") != status:
            continue
        rows.append(n)

    # sort key: gitlab_created_at falls back to created_at when missing, per business rule
    def _sort_key(row):
        if sort == "gitlab_created_at":
            dt = _parse_dt(row.get("gitlab_created_at")) or _parse_dt(row.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        else:
            dt = _parse_dt(row.get(sort)) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        # tie-breaker stable by id
        rid = row.get("id") or ""
        return (dt, rid)

    reverse = (order == "desc")
    rows.sort(key=_sort_key, reverse=reverse)

    # pagination "after_id" / "after_sort_value" (if provided)
    start_idx = 0
    after_id = None
    after_sort_val = None
    if isinstance(cursor_obj, dict):
        after_id = cursor_obj.get("after_id")
        after_sort_val = cursor_obj.get("after_sort_value")

    if after_id:
        # Find the exact element index in this filtered/sorted list; if not found, treat as "start at beginning"
        for i, r in enumerate(rows):
            if r.get("id") == after_id:
                start_idx = i + 1
                break
    elif after_sort_val is not None:
        # Best-effort: skip until strictly beyond sort_value (with tie-breaker id)
        # Parse datetime-ish sort value.
        dt_after = _parse_dt(after_sort_val)
        if dt_after is not None:
            for i, r in enumerate(rows):
                if _sort_key(r)[0] > dt_after:
                    start_idx = i
                    break

    page = rows[start_idx:start_idx + limit]
    has_more = (start_idx + limit) < len(rows)

    next_cursor = None
    if has_more and page:
        last = page[-1]
        payload = {
            "after": {
                "id": last.get("id"),
                "sort_value": (last.get("gitlab_created_at") if sort == "gitlab_created_at" else last.get(sort)) or last.get("created_at")
            },
            "sort": sort,
            "order": order
        }
        raw = json.dumps(payload, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    _log(conn.get("id"), "ok", meta={
        "project_id": project_id,
        "merge_request_id": mr.get("id"),
        "rate_bucket": conn.get("rate_limit_bucket") or conn.get("id"),
        "filters": {
            "note_type": note_type, "discussion_id": discussion_id, "author_username": author_username,
            "resolved": resolved, "system": system, "status": status
        }
    })

    return {
        "notes": page,
        "meta": {
            "total": len(rows),
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "sort": sort,
            "order": order
        }
    }

def add_merge_request_comment(project_id, body, merge_request_id=None, gitlab_mr_iid=None, **_extra):
    import json, os, datetime, re, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0207000" if __import__("os").path.isdir("./environment_mix/0207000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(connection_id, status_s, error_code=None, error_message=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "id": "glrl_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S") + ("%06d" % random.randint(0, 999999)),
            "endpoint": "add_merge_request_comment",
            "tool": "add_merge_request_comment",
            "connection_id": connection_id,
            "status": status_s,
            "error_code": error_code,
            "error_message": (error_message[:500] if isinstance(error_message, str) else error_message),
            "meta": meta or {},
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now,
            "ts": now,
        })
        _save("request_logs.json", logs)

    def _gen_id(prefix):
        return prefix + "_" + "".join(random.choice("0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ") for _ in range(26))

    # validate
    if not isinstance(project_id, str) or not re.match(r"^glp_[0-9A-Z]+$", project_id):
        _log(None, "error", "VALIDATION_ERROR", "Invalid project_id format.", {"field": "project_id"})
        return _err("VALIDATION_ERROR", "Invalid project_id format; expected ^glp_[0-9A-Z]+$.", field="project_id")
    if not isinstance(body, str) or len(body) < 1 or len(body) > 100000:
        _log(None, "error", "VALIDATION_ERROR", "Invalid body length.", {"field": "body"})
        return _err("VALIDATION_ERROR", "body must be a non-empty string up to 100000 characters.", field="body")
    if merge_request_id is None and gitlab_mr_iid is None:
        _log(None, "error", "VALIDATION_ERROR", "Missing identifier.", {})
        return _err("VALIDATION_ERROR", "Either merge_request_id or gitlab_mr_iid must be provided.")
    if merge_request_id is not None and (not isinstance(merge_request_id, str) or not re.match(r"^glmr_[0-9A-Z]+$", merge_request_id)):
        _log(None, "error", "VALIDATION_ERROR", "Invalid merge_request_id.", {"field": "merge_request_id"})
        return _err("VALIDATION_ERROR", "Invalid merge_request_id format; expected ^glmr_[0-9A-Z]+$.", field="merge_request_id")
    if gitlab_mr_iid is not None and (not isinstance(gitlab_mr_iid, int) or gitlab_mr_iid < 1):
        _log(None, "error", "VALIDATION_ERROR", "Invalid gitlab_mr_iid.", {"field": "gitlab_mr_iid"})
        return _err("VALIDATION_ERROR", "Invalid gitlab_mr_iid; must be an integer >= 1.", field="gitlab_mr_iid")

    projects = _load("projects.json")
    if not isinstance(projects, list): projects = []
    proj = next((p for p in projects if isinstance(p, dict) and p.get("id") == project_id), None)
    if not proj:
        _log(None, "error", "NOT_FOUND", "Project not found.", {"project_id": project_id})
        return _err("NOT_FOUND", "Project not found.", project_id=project_id)

    conns = _load("gitlab_connections.json")
    if not isinstance(conns, list): conns = []
    conn = None
    proj_conn_id = proj.get("connection_id")
    if isinstance(proj_conn_id, str):
        c = next((x for x in conns if isinstance(x, dict) and x.get("id") == proj_conn_id), None)
        if c and c.get("status") == "active":
            conn = c
    if conn is None:
        active = [c for c in conns if isinstance(c, dict) and c.get("status") == "active"]
        if len(active) == 1:
            conn = active[0]
    if conn is None:
        _log(proj_conn_id, "error", "UNAUTHORIZED", "No usable active GitLab connection is configured.")
        return _err("UNAUTHORIZED", "No usable active GitLab connection is configured.")

    if proj.get("connection_id") != conn.get("id"):
        _log(conn.get("id"), "error", "UNAUTHORIZED", "Project is not accessible via the active connection.", {"project_id": project_id})
        return _err("UNAUTHORIZED", "Project is not accessible via the active connection.", project_id=project_id)

    # rate limit per connection for GitLab API calls
    max_rpm = 60
    bucket = conn.get("rate_limit_bucket") or conn.get("id")
    logs = _load("request_logs.json")
    if not isinstance(logs, list): logs = []
    cutoff = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc) - datetime.timedelta(seconds=60)
    recent = 0
    for r in logs:
        if not isinstance(r, dict):
            continue
        if r.get("connection_id") != conn.get("id"):
            continue
        tool = r.get("tool") or r.get("endpoint")
        if tool not in ("add_merge_request_comment", "add_merge_request_diff_comment", "get_merge_request_diff", "get_issue_details", "set_merge_request_title", "set_merge_request_description", "sync_merge_request", "retry_note_delivery"):
            continue
        ts = r.get("created_at") or r.get("ts")
        if not isinstance(ts, str):
            continue
        try:
            dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
        except Exception:
            continue
        if dt >= cutoff:
            recent += 1
    if recent >= max_rpm:
        # allowed to mutate only connection.updated_at
        for c in conns:
            if isinstance(c, dict) and c.get("id") == conn.get("id"):
                c["updated_at"] = now
                break
        _save("gitlab_connections.json", conns)
        _log(conn.get("id"), "error", "RATE_LIMIT", "Rate limit exceeded; retry later.", {"bucket": bucket, "retry_after_sec": 60})
        return _err("RATE_LIMIT", "Rate limit exceeded; retry later.", retry_after_sec=60)

    # locate MR
    mrs = _load("merge_requests.json")
    if not isinstance(mrs, list): mrs = []
    mr = None
    for r in mrs:
        if not isinstance(r, dict):
            continue
        if r.get("project_id") != project_id:
            continue
        if merge_request_id is not None and r.get("id") == merge_request_id:
            mr = r
            break
        if merge_request_id is None and gitlab_mr_iid is not None and r.get("gitlab_mr_iid") == gitlab_mr_iid:
            mr = r
            break
    if not mr:
        _log(conn.get("id"), "error", "NOT_FOUND", "Merge request not found.", {"project_id": project_id})
        return _err("NOT_FOUND", "Merge request not found in project.", project_id=project_id)

    # Insert local note as pending_create
    notes = _load("notes.json")
    if not isinstance(notes, list): notes = []
    note = {
        "id": _gen_id("gln"),
        "merge_request_id": mr.get("id"),
        "project_id": mr.get("project_id"),
        "gitlab_note_id": None,
        "discussion_id": None,
        "note_type": "general",
        "body": body,
        "author_username": None,
        "system": False,
        "resolved": None,
        "position": None,
        "diff_file_id": None,
        "line_code": None,
        "status": "pending_create",
        "gitlab_created_at": None,
        "created_at": now,
        "updated_at": now,
    }
    notes.append(note)
    _save("notes.json", notes)

    # Attempt "GitLab creation" (offline): succeed deterministically and mark synced.
    # Business rule: on failure mark failed and log error; we won't fail offline unless connection is revoked/disabled.
    created_ok = (conn.get("status") == "active")
    if created_ok:
        # assign a plausible numeric id
        max_id = 0
        for n in notes:
            if isinstance(n, dict) and isinstance(n.get("gitlab_note_id"), int):
                if n["gitlab_note_id"] > max_id:
                    max_id = n["gitlab_note_id"]
        gitlab_note_id = max_id + 1 if max_id > 0 else random.randint(1000, 9999999)
        for n in notes:
            if isinstance(n, dict) and n.get("id") == note["id"]:
                n["gitlab_note_id"] = gitlab_note_id
                n["gitlab_created_at"] = now
                n["status"] = "synced"
                n["updated_at"] = now
                note = n
                break
        _save("notes.json", notes)
        # update connection last_successful_sync_at as an observable effect
        for c in conns:
            if isinstance(c, dict) and c.get("id") == conn.get("id"):
                c["last_successful_sync_at"] = now
                c["updated_at"] = now
                c["last_error"] = None
                break
        _save("gitlab_connections.json", conns)
        _log(conn.get("id"), "ok", None, None, {"note_id": note["id"], "merge_request_id": mr.get("id")})
        return {"note": note}

    # failure path
    err_msg = (conn.get("last_error") or "GitLab note creation failed.")
    for n in notes:
        if isinstance(n, dict) and n.get("id") == note["id"]:
            n["status"] = "failed"
            n["updated_at"] = now
            note = n
            break
    _save("notes.json", notes)
    applog = _load("application_logs.json")
    if not isinstance(applog, list): applog = []
    applog.append({"id": _gen_id("glal"), "endpoint": "add_merge_request_comment", "connection_id": conn.get("id"), "level": "error", "message": str(err_msg)[:1000], "created_at": now})
    _save("application_logs.json", applog)
    _log(conn.get("id"), "error", "CONFLICT", "GitLab note creation failed.", {"note_id": note["id"]})
    return _err("CONFLICT", "GitLab note creation failed; note stored as failed.", note_id=note["id"])

def add_merge_request_diff_comment(project_id, body, merge_request_id=None, gitlab_mr_iid=None, diff_file_id=None, line_code=None, position=None, **_extra):
    import json, os, datetime, re, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0207000" if __import__("os").path.isdir("./environment_mix/0207000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(connection_id, status_s, error_code=None, error_message=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "id": "glrl_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S") + ("%06d" % random.randint(0, 999999)),
            "endpoint": "add_merge_request_diff_comment",
            "tool": "add_merge_request_diff_comment",
            "connection_id": connection_id,
            "status": status_s,
            "error_code": error_code,
            "error_message": (error_message[:500] if isinstance(error_message, str) else error_message),
            "meta": meta or {},
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now,
            "ts": now,
        })
        _save("request_logs.json", logs)

    def _gen_id(prefix):
        return prefix + "_" + "".join(random.choice("0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ") for _ in range(26))

    # validate
    if not isinstance(project_id, str) or not re.match(r"^glp_[0-9A-Z]+$", project_id):
        _log(None, "error", "VALIDATION_ERROR", "Invalid project_id format.", {"field": "project_id"})
        return _err("VALIDATION_ERROR", "Invalid project_id format; expected ^glp_[0-9A-Z]+$.", field="project_id")
    if not isinstance(body, str) or len(body) < 1 or len(body) > 100000:
        _log(None, "error", "VALIDATION_ERROR", "Invalid body length.", {"field": "body"})
        return _err("VALIDATION_ERROR", "body must be a non-empty string up to 100000 characters.", field="body")
    if merge_request_id is None and gitlab_mr_iid is None:
        _log(None, "error", "VALIDATION_ERROR", "Missing identifier.", {})
        return _err("VALIDATION_ERROR", "Either merge_request_id or gitlab_mr_iid must be provided.")
    if merge_request_id is not None and (not isinstance(merge_request_id, str) or not re.match(r"^glmr_[0-9A-Z]+$", merge_request_id)):
        _log(None, "error", "VALIDATION_ERROR", "Invalid merge_request_id.", {"field": "merge_request_id"})
        return _err("VALIDATION_ERROR", "Invalid merge_request_id format; expected ^glmr_[0-9A-Z]+$.", field="merge_request_id")
    if gitlab_mr_iid is not None and (not isinstance(gitlab_mr_iid, int) or gitlab_mr_iid < 1):
        _log(None, "error", "VALIDATION_ERROR", "Invalid gitlab_mr_iid.", {"field": "gitlab_mr_iid"})
        return _err("VALIDATION_ERROR", "Invalid gitlab_mr_iid; must be an integer >= 1.", field="gitlab_mr_iid")
    if diff_file_id is not None and (not isinstance(diff_file_id, str) or not re.match(r"^gldf_[0-9A-Z]+$", diff_file_id)):
        _log(None, "error", "VALIDATION_ERROR", "Invalid diff_file_id.", {"field": "diff_file_id"})
        return _err("VALIDATION_ERROR", "Invalid diff_file_id format; expected ^gldf_[0-9A-Z]+$.", field="diff_file_id")
    if line_code is not None and (not isinstance(line_code, str) or len(line_code) < 1):
        _log(None, "error", "VALIDATION_ERROR", "Invalid line_code.", {"field": "line_code"})
        return _err("VALIDATION_ERROR", "line_code must be a non-empty string.", field="line_code")
    if position is not None and not isinstance(position, dict):
        _log(None, "error", "VALIDATION_ERROR", "position must be an object.", {"field": "position"})
        return _err("VALIDATION_ERROR", "position must be an object.", field="position")
    if diff_file_id is None and line_code is None and position is None:
        _log(None, "error", "VALIDATION_ERROR", "Missing diff location.", {})
        return _err("VALIDATION_ERROR", "Provide at least one of diff_file_id, line_code, or position to locate the diff.", field="diff_location")

    projects = _load("projects.json")
    if not isinstance(projects, list): projects = []
    proj = next((p for p in projects if isinstance(p, dict) and p.get("id") == project_id), None)
    if not proj:
        _log(None, "error", "NOT_FOUND", "Project not found.", {"project_id": project_id})
        return _err("NOT_FOUND", "Project not found.", project_id=project_id)

    conns = _load("gitlab_connections.json")
    if not isinstance(conns, list): conns = []
    conn = None
    proj_conn_id = proj.get("connection_id")
    if isinstance(proj_conn_id, str):
        c = next((x for x in conns if isinstance(x, dict) and x.get("id") == proj_conn_id), None)
        if c and c.get("status") == "active":
            conn = c
    if conn is None:
        active = [c for c in conns if isinstance(c, dict) and c.get("status") == "active"]
        if len(active) == 1:
            conn = active[0]
    if conn is None:
        _log(proj_conn_id, "error", "UNAUTHORIZED", "No usable active GitLab connection is configured.")
        return _err("UNAUTHORIZED", "No usable active GitLab connection is configured.")

    if proj.get("connection_id") != conn.get("id"):
        _log(conn.get("id"), "error", "UNAUTHORIZED", "Project is not accessible via the active connection.", {"project_id": project_id})
        return _err("UNAUTHORIZED", "Project is not accessible via the active connection.", project_id=project_id)

    # rate limit (GitLab API call implied)
    max_rpm = 60
    bucket = conn.get("rate_limit_bucket") or conn.get("id")
    logs = _load("request_logs.json")
    if not isinstance(logs, list): logs = []
    cutoff = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc) - datetime.timedelta(seconds=60)
    recent = 0
    for r in logs:
        if not isinstance(r, dict):
            continue
        if r.get("connection_id") != conn.get("id"):
            continue
        tool = r.get("tool") or r.get("endpoint")
        if tool not in ("add_merge_request_comment", "add_merge_request_diff_comment", "get_merge_request_diff", "get_issue_details", "set_merge_request_title", "set_merge_request_description", "sync_merge_request", "retry_note_delivery"):
            continue
        ts = r.get("created_at") or r.get("ts")
        if not isinstance(ts, str):
            continue
        try:
            dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
        except Exception:
            continue
        if dt >= cutoff:
            recent += 1
    if recent >= max_rpm:
        for c in conns:
            if isinstance(c, dict) and c.get("id") == conn.get("id"):
                c["updated_at"] = now
                break
        _save("gitlab_connections.json", conns)
        _log(conn.get("id"), "error", "RATE_LIMIT", "Rate limit exceeded; retry later.", {"bucket": bucket, "retry_after_sec": 60})
        return _err("RATE_LIMIT", "Rate limit exceeded; retry later.", retry_after_sec=60)

    # locate MR
    mrs = _load("merge_requests.json")
    if not isinstance(mrs, list): mrs = []
    mr = None
    for r in mrs:
        if not isinstance(r, dict):
            continue
        if r.get("project_id") != project_id:
            continue
        if merge_request_id is not None and r.get("id") == merge_request_id:
            mr = r
            break
        if merge_request_id is None and gitlab_mr_iid is not None and r.get("gitlab_mr_iid") == gitlab_mr_iid:
            mr = r
            break
    if not mr:
        _log(conn.get("id"), "error", "NOT_FOUND", "Merge request not found.", {"project_id": project_id})
        return _err("NOT_FOUND", "Merge request not found in project.", project_id=project_id)

    # validate diff snapshot references
    diffs = _load("merge_request_diffs.json")
    if not isinstance(diffs, list): diffs = []
    df = None
    if diff_file_id is not None:
        df = next((d for d in diffs if isinstance(d, dict) and d.get("id") == diff_file_id and d.get("merge_request_id") == mr.get("id")), None)
        if not df:
            _log(conn.get("id"), "error", "NOT_FOUND", "diff_file_id not found for merge request.", {"diff_file_id": diff_file_id})
            return _err("NOT_FOUND", "diff_file_id not found for this merge request.", diff_file_id=diff_file_id)
        # if diff snapshot is not current, refresh diffs before posting (offline: mark current for this MR)
        if df.get("is_current") is not True or df.get("status") != "active":
            # supersede existing current rows
            for d in diffs:
                if not isinstance(d, dict): 
                    continue
                if d.get("merge_request_id") != mr.get("id"):
                    continue
                if d.get("is_current") is True:
                    d["is_current"] = False
                    if d.get("status") == "active":
                        d["status"] = "superseded"
                    d["updated_at"] = now
            # make referenced diff current & active if it belongs to MR
            for d in diffs:
                if isinstance(d, dict) and d.get("id") == df.get("id"):
                    d["is_current"] = True
                    d["status"] = "active"
                    d["updated_at"] = now
                    df = d
                    break
            _save("merge_request_diffs.json", diffs)
            # update MR last_diff_synced_at for observable state
            for r in mrs:
                if isinstance(r, dict) and r.get("id") == mr.get("id"):
                    r["last_diff_synced_at"] = now
                    r["updated_at"] = now
                    mr = r
                    break
            _save("merge_requests.json", mrs)

    # If position is provided, require it to reference diff_ref_* shas when possible
    if position is not None and df is not None:
        # only validate if keys exist; be permissive with vendor payloads
        for k, dfk in (("base_sha", "diff_ref_base_sha"), ("start_sha", "diff_ref_start_sha"), ("head_sha", "diff_ref_head_sha")):
            pv = position.get(k)
            dv = df.get(dfk)
            if pv is not None and dv is not None and pv != dv:
                _log(conn.get("id"), "error", "VALIDATION_ERROR", "position SHA does not match current diff snapshot.", {"field": "position"})
                return _err("VALIDATION_ERROR", "position SHA does not match the current diff snapshot.", field="position")

    # insert local note pending_create
    notes = _load("notes.json")
    if not isinstance(notes, list): notes = []
    note = {
        "id": _gen_id("gln"),
        "merge_request_id": mr.get("id"),
        "project_id": mr.get("project_id"),
        "gitlab_note_id": None,
        "discussion_id": None,
        "note_type": "diff",
        "body": body,
        "author_username": None,
        "system": False,
        "resolved": None,
        "position": position,
        "diff_file_id": diff_file_id,
        "line_code": line_code,
        "status": "pending_create",
        "gitlab_created_at": None,
        "created_at": now,
        "updated_at": now,
    }
    notes.append(note)
    _save("notes.json", notes)

    # offline "GitLab creation": succeed when connection is active
    if conn.get("status") == "active":
        max_id = 0
        for n in notes:
            if isinstance(n, dict) and isinstance(n.get("gitlab_note_id"), int):
                max_id = max(max_id, n["gitlab_note_id"])
        gitlab_note_id = max_id + 1 if max_id > 0 else random.randint(1000, 9999999)
        for n in notes:
            if isinstance(n, dict) and n.get("id") == note["id"]:
                n["gitlab_note_id"] = gitlab_note_id
                n["gitlab_created_at"] = now
                n["status"] = "synced"
                n["updated_at"] = now
                note = n
                break
        _save("notes.json", notes)
        for c in conns:
            if isinstance(c, dict) and c.get("id") == conn.get("id"):
                c["last_successful_sync_at"] = now
                c["updated_at"] = now
                c["last_error"] = None
                break
        _save("gitlab_connections.json", conns)
        _log(conn.get("id"), "ok", None, None, {"note_id": note["id"], "merge_request_id": mr.get("id")})
        return {"note": note}

    # failure -> failed + applog
    err_msg = (conn.get("last_error") or "GitLab diff note creation failed.")
    for n in notes:
        if isinstance(n, dict) and n.get("id") == note["id"]:
            n["status"] = "failed"
            n["updated_at"] = now
            note = n
            break
    _save("notes.json", notes)
    applog = _load("application_logs.json")
    if not isinstance(applog, list): applog = []
    applog.append({"id": _gen_id("glal"), "endpoint": "add_merge_request_diff_comment", "connection_id": conn.get("id"), "level": "error", "message": str(err_msg)[:1000], "created_at": now})
    _save("application_logs.json", applog)
    _log(conn.get("id"), "error", "CONFLICT", "GitLab note creation failed.", {"note_id": note["id"]})
    return _err("CONFLICT", "GitLab note creation failed; note stored as failed.", note_id=note["id"])

def get_merge_request_diff(project_id, merge_request_id=None, gitlab_mr_iid=None, is_current=None, status=None, path=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, re, time, base64, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0207000" if __import__("os").path.isdir("./environment_mix/0207000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _new_log_id():
        return "glrl_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S") + ("%06d" % random.randint(0, 999999))

    def _log(connection_id, status_s, error_code=None, error_message=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _new_log_id(),
            "endpoint": "get_merge_request_diff",
            "tool": "get_merge_request_diff",
            "connection_id": connection_id,
            "status": status_s,
            "error_code": error_code,
            "error_message": (error_message[:500] if isinstance(error_message, str) else error_message),
            "meta": meta or {},
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now,
            "ts": now,
        })
        _save("request_logs.json", logs)

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v
        if not isinstance(v, str) or not v.strip():
            return None
        s = v.strip()
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    # Cursor is opaque; accept:
    # - our base64 json cursor
    # - a raw diff id (gldf_...)
    # - any other string (treat as no cursor)
    def _cursor_decode(cur):
        if cur is None:
            return (None, None)
        if not isinstance(cur, str) or not cur.strip():
            return (None, _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor"))
        c = cur.strip()
        if re.match(r"^gldf_[0-9A-Z]+$", c):
            return ({"after_id": c}, None)
        pad = "=" * (-len(c) % 4)
        try:
            raw = base64.urlsafe_b64decode((c + pad).encode("ascii"))
            obj = json.loads(raw.decode("utf-8"))
        except Exception:
            return ({"ignored_cursor": c}, None)
        if not isinstance(obj, dict):
            return ({"ignored_cursor": c}, None)
        after = obj.get("after")
        if after is None:
            return ({}, None)
        if not isinstance(after, dict):
            return ({"ignored_cursor": c}, None)
        return ({"after_id": after.get("id"), "after_sort_value": after.get("sort_value"), "cursor_sort": obj.get("sort"), "cursor_order": obj.get("order")}, None)

    # --- validate inputs ---
    if not isinstance(project_id, str) or not re.match(r"^glp_[0-9A-Z]+$", project_id):
        _log(None, "error", "VALIDATION_ERROR", "Invalid project_id format.", {"field": "project_id"})
        return _err("VALIDATION_ERROR", "project_id is invalid; expected ^glp_[0-9A-Z]+$.", field="project_id")

    if merge_request_id is None and gitlab_mr_iid is None:
        _log(None, "error", "VALIDATION_ERROR", "Missing merge_request_id or gitlab_mr_iid.", {"field": "merge_request_id"})
        return _err("VALIDATION_ERROR", "Either merge_request_id or gitlab_mr_iid must be provided.", field="merge_request_id")

    if merge_request_id is not None and (not isinstance(merge_request_id, str) or not re.match(r"^glmr_[0-9A-Z]+$", merge_request_id)):
        _log(None, "error", "VALIDATION_ERROR", "Invalid merge_request_id format.", {"field": "merge_request_id"})
        return _err("VALIDATION_ERROR", "merge_request_id is invalid; expected ^glmr_[0-9A-Z]+$.", field="merge_request_id")

    if gitlab_mr_iid is not None and (not isinstance(gitlab_mr_iid, int) or gitlab_mr_iid < 1):
        _log(None, "error", "VALIDATION_ERROR", "Invalid gitlab_mr_iid.", {"field": "gitlab_mr_iid"})
        return _err("VALIDATION_ERROR", "gitlab_mr_iid must be an integer >= 1.", field="gitlab_mr_iid")

    if is_current is not None and not isinstance(is_current, bool):
        _log(None, "error", "VALIDATION_ERROR", "Invalid is_current.", {"field": "is_current"})
        return _err("VALIDATION_ERROR", "is_current must be boolean.", field="is_current")

    if status is not None and status not in ("active", "superseded", "error"):
        _log(None, "error", "VALIDATION_ERROR", "Invalid status.", {"field": "status"})
        return _err("VALIDATION_ERROR", "Invalid status.", field="status")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log(None, "error", "VALIDATION_ERROR", "Invalid limit.", {"field": "limit"})
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.", field="limit")

    if sort is None:
        sort = "new_path"
    if sort not in ("new_path", "old_path", "created_at", "updated_at"):
        _log(None, "error", "VALIDATION_ERROR", "Invalid sort.", {"field": "sort"})
        return _err("VALIDATION_ERROR", "Invalid sort.", field="sort")

    if order is None:
        order = "asc"
    if order not in ("asc", "desc"):
        _log(None, "error", "VALIDATION_ERROR", "Invalid order.", {"field": "order"})
        return _err("VALIDATION_ERROR", "Invalid order.", field="order")

    cursor_obj, cursor_err = _cursor_decode(cursor)
    if cursor_err:
        _log(None, "error", cursor_err["error"]["code"], cursor_err["error"]["message"], {"field": "cursor"})
        return cursor_err

    # --- resolve project & connection ---
    projects = _load("projects.json")
    if not isinstance(projects, list):
        projects = []
    proj = None
    for p in projects:
        if isinstance(p, dict) and p.get("id") == project_id:
            proj = p
            break
    if not proj:
        _log(None, "error", "NOT_FOUND", "Project not found.", {"project_id": project_id})
        return _err("NOT_FOUND", "Project not found.", project_id=project_id)

    conns = _load("gitlab_connections.json")
    if not isinstance(conns, list):
        conns = []
    conn = None
    for c in conns:
        if isinstance(c, dict) and c.get("id") == proj.get("connection_id") and c.get("status") == "active":
            conn = c
            break
    if conn is None:
        for c in conns:
            if isinstance(c, dict) and c.get("id") == proj.get("connection_id") and c.get("status") in ("active", "disabled"):
                conn = c
                break
    if conn is None:
        _log(None, "error", "UNAUTHORIZED", "No usable GitLab connection for this project.", {"project_id": project_id})
        return _err("UNAUTHORIZED", "No usable GitLab connection for this project.", rule="Tools operate within exactly one gitlab_connections row; resolve via the project's owning connection.")

    # --- resolve MR ---
    mrs = _load("merge_requests.json")
    if not isinstance(mrs, list):
        mrs = []
    mr = None
    if merge_request_id is not None:
        for r in mrs:
            if isinstance(r, dict) and r.get("id") == merge_request_id:
                mr = r
                break
        if not mr:
            _log(conn.get("id"), "error", "NOT_FOUND", "Merge request not found.", {"merge_request_id": merge_request_id})
            return _err("NOT_FOUND", "Merge request not found.", merge_request_id=merge_request_id)
        if mr.get("project_id") != project_id:
            _log(conn.get("id"), "error", "CONFLICT", "merge_request_id does not belong to project_id.", {"project_id": project_id, "merge_request_id": merge_request_id})
            return _err("CONFLICT", "merge_request_id does not belong to project_id.", project_id=project_id, merge_request_id=merge_request_id)
    else:
        for r in mrs:
            if isinstance(r, dict) and r.get("project_id") == project_id and r.get("gitlab_mr_iid") == gitlab_mr_iid:
                mr = r
                break
        if not mr:
            _log(conn.get("id"), "error", "NOT_FOUND", "Merge request not found for project and IID.", {"project_id": project_id, "gitlab_mr_iid": gitlab_mr_iid})
            return _err("NOT_FOUND", "Merge request not found for project and gitlab_mr_iid.", project_id=project_id, gitlab_mr_iid=gitlab_mr_iid)

    diffs = _load("merge_request_diffs.json")
    if not isinstance(diffs, list):
        diffs = []

    rows = []
    for d in diffs:
        if not isinstance(d, dict):
            continue
        if d.get("merge_request_id") != mr.get("id"):
            continue
        if is_current is not None and d.get("is_current") != is_current:
            continue
        if status is not None and d.get("status") != status:
            continue
        if path is not None:
            if not isinstance(path, str) or not path:
                _log(conn.get("id"), "error", "VALIDATION_ERROR", "Invalid path.", {"field": "path"})
                return _err("VALIDATION_ERROR", "path must be a non-empty string when provided.", field="path")
            if path not in (d.get("old_path") or "") and path not in (d.get("new_path") or ""):
                # substring match: "matches old_path or new_path"
                if (path not in (d.get("old_path") or "")) and (path not in (d.get("new_path") or "")):
                    continue
        rows.append(d)

    def _sort_key(row):
        if sort in ("new_path", "old_path"):
            sval = row.get(sort) or ""
            return (sval, row.get("id") or "")
        dt = _parse_dt(row.get(sort)) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        return (dt, row.get("id") or "")

    reverse = (order == "desc")
    rows.sort(key=_sort_key, reverse=reverse)

    start_idx = 0
    after_id = None
    after_sort_val = None
    if isinstance(cursor_obj, dict):
        after_id = cursor_obj.get("after_id")
        after_sort_val = cursor_obj.get("after_sort_value")

    if after_id:
        for i, r in enumerate(rows):
            if r.get("id") == after_id:
                start_idx = i + 1
                break
    elif after_sort_val is not None and sort in ("created_at", "updated_at"):
        dt_after = _parse_dt(after_sort_val)
        if dt_after is not None:
            for i, r in enumerate(rows):
                if _sort_key(r)[0] > dt_after:
                    start_idx = i
                    break

    page = rows[start_idx:start_idx + limit]
    has_more = (start_idx + limit) < len(rows)

    next_cursor = None
    if has_more and page:
        last = page[-1]
        payload = {
            "after": {
                "id": last.get("id"),
                "sort_value": last.get(sort)
            },
            "sort": sort,
            "order": order
        }
        raw = json.dumps(payload, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    _log(conn.get("id"), "ok", meta={
        "project_id": project_id,
        "merge_request_id": mr.get("id"),
        "rate_bucket": conn.get("rate_limit_bucket") or conn.get("id"),
        "filters": {"is_current": is_current, "status": status, "path": path}
    })

    return {
        "diffs": page,
        "meta": {
            "total": len(rows),
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "sort": sort,
            "order": order
        }
    }

