    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_log_id():
        return "glrl_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S") + ("%06d" % random.randint(0, 999999))

    def _log(connection_id, status_s, error_code=None, error_message=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _new_log_id(),
            "endpoint": "get_issue_details",
            "tool": "get_issue_details",
            "connection_id": connection_id,
            "status": status_s,
            "error_code": error_code,
            "error_message": (error_message[:500] if isinstance(error_message, str) else error_message),
            "meta": meta or {},
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now,
            "ts": now,
        })
        _save("request_logs.json", logs)

    # validate
    if not isinstance(project_id, str) or not re.match(r"^glp_[0-9A-Z]+$", project_id):
        _log(None, "error", "VALIDATION_ERROR", "Invalid project_id format.", {"field": "project_id"})
        return _err("VALIDATION_ERROR", "project_id is invalid; expected ^glp_[0-9A-Z]+$.", field="project_id")
    if not isinstance(issue_iid, int) or issue_iid < 1:
        _log(None, "error", "VALIDATION_ERROR", "Invalid issue_iid.", {"field": "issue_iid"})
        return _err("VALIDATION_ERROR", "issue_iid must be an integer >= 1.", field="issue_iid")

    projects = _load("projects.json")
    if not isinstance(projects, list):
        projects = []
    proj = None
    for p in projects:
        if isinstance(p, dict) and p.get("id") == project_id:
            proj = p
            break
    if not proj:
        _log(None, "error", "NOT_FOUND", "Project not found.", {"project_id": project_id})
        return _err("NOT_FOUND", "Project not found.", project_id=project_id)

    conns = _load("gitlab_connections.json")
    if not isinstance(conns, list):
        conns = []
    conn = None
    for c in conns:
        if isinstance(c, dict) and c.get("id") == proj.get("connection_id") and c.get("status") == "active":
            conn = c
            break
    if conn is None:
        for c in conns:
            if isinstance(c, dict) and c.get("id") == proj.get("connection_id") and c.get("status") in ("active", "disabled"):
                conn = c
                break
    if conn is None:
        _log(None, "error", "UNAUTHORIZED", "No usable GitLab connection for this project.", {"project_id": project_id})
        return _err("UNAUTHORIZED", "No usable GitLab connection for this project.", rule="Tools operate within exactly one gitlab_connections row; resolve via the project's owning connection.")

    # Issues are not modeled in this datastore; serve from mirror if present, else NOT_FOUND.
    issues = _load("issues.json")
    if not isinstance(issues, list):
        issues = []

    issue = None
    for it in issues:
        if not isinstance(it, dict):
            continue
        if it.get("project_id") != project_id:
            continue
        if it.get("gitlab_issue_iid") == issue_iid:
            issue = it
            break

    if not issue:
        _log(conn.get("id"), "error", "NOT_FOUND", "Issue not found in mirror for project.", {"project_id": project_id, "issue_iid": issue_iid})
        return _err("NOT_FOUND", "Issue not found in mirror for project.", project_id=project_id, issue_iid=issue_iid)

    _log(conn.get("id"), "ok", meta={"project_id": project_id, "issue_iid": issue_iid, "rate_bucket": conn.get("rate_limit_bucket") or conn.get("id")})
    return {"issue": issue}

