    if not isinstance(description, str):
        _log(None, "error", "VALIDATION_ERROR", "description must be a string.", {"field": "description"})
        return _err("VALIDATION_ERROR", "description must be a string.", field="description")

    mrs = _load("merge_requests.json")
    if not isinstance(mrs, list): mrs = []
    mr = next((m for m in mrs if isinstance(m, dict) and m.get("id") == merge_request_id), None)
    if not mr:
        _log(None, "error", "NOT_FOUND", "Merge request not found.", {"merge_request_id": merge_request_id})
        return _err("NOT_FOUND", "Merge request not found.", merge_request_id=merge_request_id)

    projects = _load("projects.json")
    if not isinstance(projects, list): projects = []
    proj = next((p for p in projects if isinstance(p, dict) and p.get("id") == mr.get("project_id")), None)
    if not proj:
        _log(None, "error", "CONFLICT", "Merge request refers to missing project.", {"merge_request_id": merge_request_id})
        return _err("CONFLICT", "Merge request refers to a missing project.", merge_request_id=merge_request_id)

    conns = _load("gitlab_connections.json")
    if not isinstance(conns, list): conns = []
    conn = None
    proj_conn_id = proj.get("connection_id")
    if isinstance(proj_conn_id, str):
        c = next((x for x in conns if isinstance(x, dict) and x.get("id") == proj_conn_id), None)
        if c and c.get("status") == "active":
            conn = c
    if conn is None:
        active = [c for c in conns if isinstance(c, dict) and c.get("status") == "active"]
        if len(active) == 1:
            conn = active[0]
    if conn is None:
        _log(proj_conn_id, "error", "UNAUTHORIZED", "No usable active GitLab connection is configured.")
        return _err("UNAUTHORIZED", "No usable active GitLab connection is configured.")

    if proj.get("connection_id") != conn.get("id"):
        _log(conn.get("id"), "error", "UNAUTHORIZED", "Merge request is not accessible via the active connection.", {"merge_request_id": merge_request_id})
        return _err("UNAUTHORIZED", "Merge request is not accessible via the active connection.", merge_request_id=merge_request_id)

    # rate limit (GitLab API call implied)
    max_rpm = 60
    logs = _load("request_logs.json")
    if not isinstance(logs, list): logs = []
    cutoff = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc) - datetime.timedelta(seconds=60)
    recent = 0
    for r in logs:
        if not isinstance(r, dict):
            continue
        if r.get("connection_id") != conn.get("id"):
            continue
        tool = r.get("tool") or r.get("endpoint")
        if tool not in ("add_merge_request_comment", "add_merge_request_diff_comment", "get_merge_request_diff", "get_issue_details", "set_merge_request_title", "set_merge_request_description", "sync_merge_request", "retry_note_delivery"):
            continue
        ts = r.get("created_at") or r.get("ts")
        if not isinstance(ts, str):
            continue
        try:
            dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
        except Exception:
            continue
        if dt >= cutoff:
            recent += 1
    if recent >= max_rpm:
        for c in conns:
            if isinstance(c, dict) and c.get("id") == conn.get("id"):
                c["updated_at"] = now
                break
        _save("gitlab_connections.json", conns)
        _log(conn.get("id"), "error", "RATE_LIMIT", "Rate limit exceeded; retry later.", {"retry_after_sec": 60})
        return _err("RATE_LIMIT", "Rate limit exceeded; retry later.", retry_after_sec=60)

    # update locally first, then "GitLab update" (offline success); on failure we'd revert or mark stale.
    old_desc = mr.get("description")
    updated = None
    for r in mrs:
        if isinstance(r, dict) and r.get("id") == merge_request_id:
            r["description"] = description
            r["updated_at"] = now
            updated = r
            break
    if not updated:
        _log(conn.get("id"), "error", "NOT_FOUND", "Merge request not found.", {"merge_request_id": merge_request_id})
        return _err("NOT_FOUND", "Merge request not found.", merge_request_id=merge_request_id)
    _save("merge_requests.json", mrs)

    # offline GitLab update: succeed only if connection active
    if conn.get("status") == "active":
        # keep status active; mark synced time
        for r in mrs:
            if isinstance(r, dict) and r.get("id") == merge_request_id:
                if r.get("status") == "syncing":
                    r["status"] = "active"
                r["last_synced_at"] = now
                r["updated_at"] = now
                updated = r
                break
        _save("merge_requests.json", mrs)
        for c in conns:
            if isinstance(c, dict) and c.get("id") == conn.get("id"):
                c["last_successful_sync_at"] = now
                c["updated_at"] = now
                c["last_error"] = None
                break
        _save("gitlab_connections.json", conns)
        _log(conn.get("id"), "ok", None, None, {"merge_request_id": merge_request_id})
        return {"merge_request": updated}

    # failure: revert local title or mark error (choose consistent rule: revert)
    for r in mrs:
        if isinstance(r, dict) and r.get("id") == merge_request_id:
            r["description"] = old_desc
            r["status"] = "error"
            r["updated_at"] = now
            updated = r
            break
    _save("merge_requests.json", mrs)
    _log(conn.get("id"), "error", "CONFLICT", "GitLab update failed; description reverted and status set to error.", {"merge_request_id": merge_request_id})
    return _err("CONFLICT", "GitLab update failed; description reverted and status set to error.", merge_request_id=merge_request_id)

