def sync_project(project_id, mode=None, **_extra):
    import json, os, datetime, re, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0207000" if __import__("os").path.isdir("./environment_mix/0207000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _new_log_id():
        return "glrl_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S") + ("%06d" % random.randint(0, 999999))

    def _log(connection_id, status_s, error_code=None, error_message=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _new_log_id(),
            "endpoint": "sync_project",
            "tool": "sync_project",
            "connection_id": connection_id,
            "status": status_s,
            "error_code": error_code,
            "error_message": (error_message or "")[:500] if isinstance(error_message, str) else error_message,
            "meta": meta or {},
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now,
            "ts": now,
        })
        _save("request_logs.json", logs)

    def _rate_bucket(conn):
        return conn.get("rate_limit_bucket") or conn.get("id")

    def _count_recent_bucket_calls(bucket, seconds=60):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return 0
        cutoff = datetime.datetime.utcnow().replace(tzinfo=None) - datetime.timedelta(seconds=seconds)
        c = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("endpoint") not in ("sync_project", "update_merge_request", "retry_note_delivery", "add_merge_request_comment", "add_merge_request_diff_comment", "get_merge_request_details", "get_merge_request_diff"):
                continue
            meta = r.get("meta") or {}
            if not isinstance(meta, dict) or meta.get("rate_bucket") != bucket:
                continue
            ts = r.get("created_at") or r.get("ts")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= cutoff and r.get("status") in ("ok", "error"):
                c += 1
        return c

    def _max_rpm(conn):
        for k in ("max_requests_per_minute", "requests_per_minute", "rpm_limit"):
            v = conn.get(k)
            if isinstance(v, int) and v > 0:
                return v
        return 60

    # validate
    if not isinstance(project_id, str) or not re.match(r"^glp_[0-9A-Z]+$", project_id):
        _log(None, "error", "VALIDATION_ERROR", "Invalid project_id format.", {"field": "project_id"})
        return _err("VALIDATION_ERROR", "Invalid project_id format; expected ^glp_[0-9A-Z]+$.", field="project_id")

    if mode is None:
        mode = "lazy"
    if mode not in ("lazy", "full"):
        _log(None, "error", "VALIDATION_ERROR", "Invalid mode.", {"field": "mode"})
        return _err("VALIDATION_ERROR", "mode must be one of: lazy, full.", field="mode")

    projects = _load("projects.json")
    if not isinstance(projects, list): projects = []
    proj_idx = None
    proj = None
    for i, p in enumerate(projects):
        if isinstance(p, dict) and p.get("id") == project_id:
            proj_idx = i
            proj = p
            break
    if not proj:
        _log(None, "error", "NOT_FOUND", "Project not found.", {"project_id": project_id})
        return _err("NOT_FOUND", "Project not found.", project_id=project_id)

    conns = _load("gitlab_connections.json")
    if not isinstance(conns, list): conns = []

    # Find an active connection that can serve this project (do not require uniqueness)
    conn = next((c for c in conns if isinstance(c, dict) and c.get("id") == proj.get("connection_id") and c.get("status") == "active"), None)
    if not conn:
        for c in conns:
            if not isinstance(c, dict) or c.get("status") != "active":
                continue
            if c.get("id") == proj.get("connection_id"):
                conn = c
                break
    if not conn:
        _log(proj.get("connection_id"), "error", "UNAUTHORIZED", "No active GitLab connection can serve this project.", {"project_id": project_id})
        return _err("UNAUTHORIZED", "No active GitLab connection can serve this project.", project_id=project_id)

    # Rate limit (quota) is per connection/bucket; if exceeded, do not mutate local state except connection.updated_at
    bucket = _rate_bucket(conn)
    used = _count_recent_bucket_calls(bucket, 60)
    max_rpm = _max_rpm(conn)
    if used >= max_rpm:
        # update connection.updated_at only
        changed = False
        for c in conns:
            if isinstance(c, dict) and c.get("id") == conn.get("id"):
                c["updated_at"] = now
                changed = True
                break
        if changed:
            _save("gitlab_connections.json", conns)
        _log(conn.get("id"), "error", "RATE_LIMIT", "GitLab API rate limit exceeded for this connection.", {"rate_bucket": bucket, "used": used, "max_rpm": max_rpm})
        return _err("RATE_LIMIT", "GitLab API rate limit exceeded; retry later.", retry_after_seconds=60, rate_bucket=bucket)

    # Perform a best-effort local "sync" (offline): update timestamps and statuses coherently.
    # Project transitions: keep status as-is (cannot infer GitLab), but refresh last_synced_at.
    proj["last_synced_at"] = now
    proj["updated_at"] = now
    projects[proj_idx] = proj

    # Related MRs: mark syncing then active (or keep error if already error and mode is lazy).
    mrs = _load("merge_requests.json")
    if not isinstance(mrs, list): mrs = []
    updated_mrs = 0
    for r in mrs:
        if not isinstance(r, dict) or r.get("project_id") != project_id:
            continue
        # legal transitions per schema
        prev = r.get("status")
        if prev in ("active", "stale", "error"):
            r["status"] = "syncing"
            r["updated_at"] = now
            r["last_synced_at"] = now
            # Complete the sync (offline immediate)
            if prev == "error" and mode == "lazy":
                # keep error (best-effort)
                r["status"] = "error"
            else:
                r["status"] = "active"
            r["updated_at"] = now
            updated_mrs += 1

    # For full mode, also mark current diffs for these MRs as refreshed (no new data inserted offline).
    diffs = _load("merge_request_diffs.json")
    if not isinstance(diffs, list): diffs = []
    updated_diffs = 0
    if mode == "full":
        mr_ids = set([r.get("id") for r in mrs if isinstance(r, dict) and r.get("project_id") == project_id])
        for d in diffs:
            if not isinstance(d, dict) or d.get("merge_request_id") not in mr_ids:
                continue
            if d.get("is_current") is True and d.get("status") == "active":
                d["updated_at"] = now
                updated_diffs += 1

    _save("projects.json", projects)
    _save("merge_requests.json", mrs)
    if mode == "full":
        _save("merge_request_diffs.json", diffs)

    # record successful sync on connection
    for c in conns:
        if isinstance(c, dict) and c.get("id") == conn.get("id"):
            c["last_successful_sync_at"] = now
            c["last_error"] = None
            c["updated_at"] = now
            break
    _save("gitlab_connections.json", conns)

    _log(conn.get("id"), "ok", None, None, {"project_id": project_id, "mode": mode, "updated_mrs": updated_mrs, "updated_diffs": updated_diffs, "rate_bucket": bucket})
    return {"project": proj, "connection_id": conn.get("id"), "mode": mode}

def sync_merge_request(project_id, merge_request_id=None, gitlab_mr_iid=None, include_diffs=None, include_notes=None, **_extra):
    import json, os, datetime, re, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0207000" if __import__("os").path.isdir("./environment_mix/0207000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(connection_id, status_s, error_code=None, error_message=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "id": "glrl_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S") + ("%06d" % random.randint(0, 999999)),
            "endpoint": "sync_merge_request",
            "tool": "sync_merge_request",
            "connection_id": connection_id,
            "status": status_s,
            "error_code": error_code,
            "error_message": (error_message[:500] if isinstance(error_message, str) else error_message),
            "meta": meta or {},
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now,
            "ts": now,
        })
        _save("request_logs.json", logs)

    # validate
    if not isinstance(project_id, str) or not re.match(r"^glp_[0-9A-Z]+$", project_id):
        _log(None, "error", "VALIDATION_ERROR", "Invalid project_id format.", {"field": "project_id"})
        return _err("VALIDATION_ERROR", "Invalid project_id format; expected ^glp_[0-9A-Z]+$.", field="project_id")
    if merge_request_id is None and gitlab_mr_iid is None:
        _log(None, "error", "VALIDATION_ERROR", "Missing merge request identifier.", {})
        return _err("VALIDATION_ERROR", "Either merge_request_id or gitlab_mr_iid must be provided.")
    if merge_request_id is not None and (not isinstance(merge_request_id, str) or not re.match(r"^glmr_[0-9A-Z]+$", merge_request_id)):
        _log(None, "error", "VALIDATION_ERROR", "Invalid merge_request_id.", {"field": "merge_request_id"})
        return _err("VALIDATION_ERROR", "Invalid merge_request_id format; expected ^glmr_[0-9A-Z]+$.", field="merge_request_id")
    if gitlab_mr_iid is not None and (not isinstance(gitlab_mr_iid, int) or gitlab_mr_iid < 1):
        _log(None, "error", "VALIDATION_ERROR", "Invalid gitlab_mr_iid.", {"field": "gitlab_mr_iid"})
        return _err("VALIDATION_ERROR", "Invalid gitlab_mr_iid; must be an integer >= 1.", field="gitlab_mr_iid")
    if include_diffs is not None and not isinstance(include_diffs, bool):
        _log(None, "error", "VALIDATION_ERROR", "include_diffs must be boolean.", {"field": "include_diffs"})
        return _err("VALIDATION_ERROR", "include_diffs must be a boolean.", field="include_diffs")
    if include_notes is not None and not isinstance(include_notes, bool):
        _log(None, "error", "VALIDATION_ERROR", "include_notes must be boolean.", {"field": "include_notes"})
        return _err("VALIDATION_ERROR", "include_notes must be a boolean.", field="include_notes")

    projects = _load("projects.json")
    if not isinstance(projects, list): projects = []
    proj = next((p for p in projects if isinstance(p, dict) and p.get("id") == project_id), None)
    if not proj:
        _log(None, "error", "NOT_FOUND", "Project not found.", {"project_id": project_id})
        return _err("NOT_FOUND", "Project not found.", project_id=project_id)

    conns = _load("gitlab_connections.json")
    if not isinstance(conns, list): conns = []
    conn = None
    proj_conn_id = proj.get("connection_id")
    if isinstance(proj_conn_id, str):
        c = next((x for x in conns if isinstance(x, dict) and x.get("id") == proj_conn_id), None)
        if c and c.get("status") == "active":
            conn = c
    if conn is None:
        active = [c for c in conns if isinstance(c, dict) and c.get("status") == "active"]
        if len(active) == 1:
            conn = active[0]
    if conn is None:
        _log(proj_conn_id, "error", "UNAUTHORIZED", "No usable active GitLab connection is configured.")
        return _err("UNAUTHORIZED", "No usable active GitLab connection is configured.")

    if proj.get("connection_id") != conn.get("id"):
        _log(conn.get("id"), "error", "UNAUTHORIZED", "Project is not accessible via the active connection.", {"project_id": project_id})
        return _err("UNAUTHORIZED", "Project is not accessible via the active connection.", project_id=project_id)

    # rate limit (GitLab API call implied)
    max_rpm = 60
    logs = _load("request_logs.json")
    if not isinstance(logs, list): logs = []
    cutoff = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc) - datetime.timedelta(seconds=60)
    recent = 0
    for r in logs:
        if not isinstance(r, dict):
            continue
        if r.get("connection_id") != conn.get("id"):
            continue
        tool = r.get("tool") or r.get("endpoint")
        if tool not in ("add_merge_request_comment", "add_merge_request_diff_comment", "get_merge_request_diff", "get_issue_details", "set_merge_request_title", "set_merge_request_description", "sync_merge_request", "retry_note_delivery"):
            continue
        ts = r.get("created_at") or r.get("ts")
        if not isinstance(ts, str):
            continue
        try:
            dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
        except Exception:
            continue
        if dt >= cutoff:
            recent += 1
    if recent >= max_rpm:
        for c in conns:
            if isinstance(c, dict) and c.get("id") == conn.get("id"):
                c["updated_at"] = now
                break
        _save("gitlab_connections.json", conns)
        _log(conn.get("id"), "error", "RATE_LIMIT", "Rate limit exceeded; retry later.", {"retry_after_sec": 60})
        return _err("RATE_LIMIT", "Rate limit exceeded; retry later.", retry_after_sec=60)

    mrs = _load("merge_requests.json")
    if not isinstance(mrs, list): mrs = []
    mr = None
    for r in mrs:
        if not isinstance(r, dict):
            continue
        if r.get("project_id") != project_id:
            continue
        if merge_request_id is not None and r.get("id") == merge_request_id:
            mr = r
            break
        if merge_request_id is None and gitlab_mr_iid is not None and r.get("gitlab_mr_iid") == gitlab_mr_iid:
            mr = r
            break
    if not mr:
        _log(conn.get("id"), "error", "NOT_FOUND", "Merge request not found.", {"project_id": project_id})
        return _err("NOT_FOUND", "Merge request not found in project.", project_id=project_id)

    allowed = {
        "active": {"stale", "syncing", "error"},
        "stale": {"syncing", "active", "error"},
        "syncing": {"active", "error"},
        "error": {"syncing", "stale"},
    }

    cur = mr.get("status")
    if cur not in allowed or "syncing" not in allowed[cur]:
        _log(conn.get("id"), "error", "INVALID_TRANSITION", "Cannot transition merge request to syncing from current status.", {"from": cur, "to": "syncing"})
        return _err("INVALID_TRANSITION", "Cannot transition merge request status to syncing from current status.", from_status=cur, to_status="syncing")

    # set syncing
    for r in mrs:
        if isinstance(r, dict) and r.get("id") == mr.get("id"):
            r["status"] = "syncing"
            r["updated_at"] = now
            mr = r
            break
    _save("merge_requests.json", mrs)

    # offline "refresh" -> active
    for r in mrs:
        if isinstance(r, dict) and r.get("id") == mr.get("id"):
            r["status"] = "active"
            r["last_synced_at"] = now
            r["updated_at"] = now
            mr = r
            break
    _save("merge_requests.json", mrs)

    # optionally refresh diffs/notes: cannot fabricate, but we can mark timestamps / current flags coherently
    if include_diffs:
        diffs = _load("merge_request_diffs.json")
        if not isinstance(diffs, list): diffs = []
        # ensure at most one current: keep newest updated_at as current if multiples
        current = [d for d in diffs if isinstance(d, dict) and d.get("merge_request_id") == mr.get("id") and d.get("is_current") is True]
        if len(current) > 1:
            # keep the one with max updated_at
            def _ts(d):
                s = d.get("updated_at") or d.get("created_at") or ""
                try:
                    return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).timestamp()
                except Exception:
                    return 0.0
            keep = max(current, key=_ts)
            for d in diffs:
                if not isinstance(d, dict): 
                    continue
                if d.get("merge_request_id") != mr.get("id"): 
                    continue
                if d.get("id") != keep.get("id") and d.get("is_current") is True:
                    d["is_current"] = False
                    if d.get("status") == "active":
                        d["status"] = "superseded"
                    d["updated_at"] = now
            _save("merge_request_diffs.json", diffs)
        # update MR timestamp
        for r in mrs:
            if isinstance(r, dict) and r.get("id") == mr.get("id"):
                r["last_diff_synced_at"] = now
                r["updated_at"] = now
                mr = r
                break
        _save("merge_requests.json", mrs)

    if include_notes:
        # update connection sync timestamp as observable side-effect
        for c in conns:
            if isinstance(c, dict) and c.get("id") == conn.get("id"):
                c["last_successful_sync_at"] = now
                c["updated_at"] = now
                c["last_error"] = None
                break
        _save("gitlab_connections.json", conns)

    _log(conn.get("id"), "ok", None, None, {"merge_request_id": mr.get("id"), "include_diffs": bool(include_diffs), "include_notes": bool(include_notes)})
    return {"merge_request": mr}

def update_merge_request(project_id, merge_request_id=None, gitlab_mr_iid=None, title=None, description=None, **_extra):
    import json, os, datetime, re, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0207000" if __import__("os").path.isdir("./environment_mix/0207000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _new_log_id():
        return "glrl_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S") + ("%06d" % random.randint(0, 999999))

    def _log(connection_id, status_s, error_code=None, error_message=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _new_log_id(),
            "endpoint": "update_merge_request",
            "tool": "update_merge_request",
            "connection_id": connection_id,
            "status": status_s,
            "error_code": error_code,
            "error_message": (error_message[:500] if isinstance(error_message, str) else error_message),
            "meta": meta or {},
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now,
            "ts": now,
        })
        _save("request_logs.json", logs)

    def _rate_bucket(conn):
        return conn.get("rate_limit_bucket") or conn.get("id")

    def _count_recent_bucket_calls(bucket, seconds=60):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return 0
        cutoff = datetime.datetime.utcnow().replace(tzinfo=None) - datetime.timedelta(seconds=seconds)
        c = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            meta = r.get("meta") or {}
            if not isinstance(meta, dict) or meta.get("rate_bucket") != bucket:
                continue
            ts = r.get("created_at") or r.get("ts")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= cutoff and r.get("status") in ("ok", "error"):
                c += 1
        return c

    def _max_rpm(conn):
        for k in ("max_requests_per_minute", "requests_per_minute", "rpm_limit"):
            v = conn.get(k)
            if isinstance(v, int) and v > 0:
                return v
        return 60

    # validate
    if not isinstance(project_id, str) or not re.match(r"^glp_[0-9A-Z]+$", project_id):
        _log(None, "error", "VALIDATION_ERROR", "Invalid project_id format.", {"field": "project_id"})
        return _err("VALIDATION_ERROR", "Invalid project_id format; expected ^glp_[0-9A-Z]+$.", field="project_id")

    if merge_request_id is None and gitlab_mr_iid is None:
        _log(None, "error", "VALIDATION_ERROR", "Either merge_request_id or gitlab_mr_iid is required.", {"field": "merge_request_id"})
        return _err("VALIDATION_ERROR", "Either merge_request_id or gitlab_mr_iid must be provided.", field="merge_request_id")

    if merge_request_id is not None:
        if not isinstance(merge_request_id, str) or not re.match(r"^glmr_[0-9A-Z]+$", merge_request_id):
            _log(None, "error", "VALIDATION_ERROR", "Invalid merge_request_id format.", {"field": "merge_request_id"})
            return _err("VALIDATION_ERROR", "Invalid merge_request_id format; expected ^glmr_[0-9A-Z]+$.", field="merge_request_id")

    if gitlab_mr_iid is not None:
        if not isinstance(gitlab_mr_iid, int) or gitlab_mr_iid < 1:
            _log(None, "error", "VALIDATION_ERROR", "Invalid gitlab_mr_iid.", {"field": "gitlab_mr_iid"})
            return _err("VALIDATION_ERROR", "gitlab_mr_iid must be an integer >= 1.", field="gitlab_mr_iid")

    if title is None and description is None:
        _log(None, "error", "VALIDATION_ERROR", "No fields provided.", {"field": "title"})
        return _err("VALIDATION_ERROR", "At least one of title or description must be provided.", field="title")

    if title is not None and (not isinstance(title, str) or len(title) < 1 or len(title) > 5000):
        _log(None, "error", "VALIDATION_ERROR", "Invalid title.", {"field": "title"})
        return _err("VALIDATION_ERROR", "title must be a string with length between 1 and 5000.", field="title")

    if description is not None and (not isinstance(description, str) or len(description) > 1048576):
        _log(None, "error", "VALIDATION_ERROR", "Invalid description.", {"field": "description"})
        return _err("VALIDATION_ERROR", "description must be a string with length <= 1048576.", field="description")

    projects = _load("projects.json")
    if not isinstance(projects, list): projects = []
    project = next((p for p in projects if isinstance(p, dict) and p.get("id") == project_id), None)
    if not project:
        _log(None, "error", "NOT_FOUND", "Project not found.", {"project_id": project_id})
        return _err("NOT_FOUND", "Project not found.", project_id=project_id)

    conns = _load("gitlab_connections.json")
    if not isinstance(conns, list): conns = []
    conn = next((c for c in conns if isinstance(c, dict) and c.get("id") == project.get("connection_id") and c.get("status") == "active"), None)
    if not conn:
        # do not require uniqueness; find any active that can serve this project
        for c in conns:
            if isinstance(c, dict) and c.get("status") == "active" and c.get("id") == project.get("connection_id"):
                conn = c
                break
    if not conn:
        _log(project.get("connection_id"), "error", "UNAUTHORIZED", "No active GitLab connection can serve this project.", {"project_id": project_id})
        return _err("UNAUTHORIZED", "No active GitLab connection can serve this project.", project_id=project_id)

    # rate limit on GitLab update attempt
    bucket = _rate_bucket(conn)
    used = _count_recent_bucket_calls(bucket, 60)
    max_rpm = _max_rpm(conn)
    if used >= max_rpm:
        # update connection.updated_at only
        for c in conns:
            if isinstance(c, dict) and c.get("id") == conn.get("id"):
                c["updated_at"] = now
                break
        _save("gitlab_connections.json", conns)
        _log(conn.get("id"), "error", "RATE_LIMIT", "GitLab API rate limit exceeded for this connection.", {"rate_bucket": bucket, "used": used, "max_rpm": max_rpm})
        return _err("RATE_LIMIT", "GitLab API rate limit exceeded; retry later.", retry_after_seconds=60, rate_bucket=bucket)

    mrs = _load("merge_requests.json")
    if not isinstance(mrs, list): mrs = []

    mr_idx = None
    mr = None
    if merge_request_id is not None:
        for i, r in enumerate(mrs):
            if isinstance(r, dict) and r.get("id") == merge_request_id and r.get("project_id") == project_id:
                mr_idx = i
                mr = r
                break
    else:
        for i, r in enumerate(mrs):
            if isinstance(r, dict) and r.get("project_id") == project_id and r.get("gitlab_mr_iid") == gitlab_mr_iid:
                mr_idx = i
                mr = r
                break

    if not mr:
        _log(conn.get("id"), "error", "NOT_FOUND", "Merge request not found.", {"project_id": project_id})
        return _err("NOT_FOUND", "Merge request not found.", project_id=project_id, merge_request_id=merge_request_id, gitlab_mr_iid=gitlab_mr_iid)

    # apply local update with lifecycle tracking; then "attempt GitLab update" best-effort offline:
    old_title = mr.get("title")
    old_desc = mr.get("description")

    # move to syncing if legal
    prev_status = mr.get("status")
    if prev_status in ("active", "stale", "error"):
        mr["status"] = "syncing"
    elif prev_status == "syncing":
        pass
    else:
        _log(conn.get("id"), "error", "INVALID_TRANSITION", "Illegal merge request status transition.", {"from": prev_status, "to": "syncing"})
        return _err("INVALID_TRANSITION", "Illegal merge request status transition.", from_status=prev_status, to_status="syncing")

    if title is not None:
        mr["title"] = title
    if description is not None:
        mr["description"] = description
    mr["updated_at"] = now
    mrs[mr_idx] = mr
    _save("merge_requests.json", mrs)

    # Offline GitLab update simulation: if connection indicates recent auth/rate errors, fail; otherwise succeed.
    last_err = conn.get("last_error")
    fail = isinstance(last_err, str) and (last_err.startswith("401") or last_err.startswith("403") or last_err.startswith("429") or "DNS" in last_err)
    if fail:
        # Consistency policy: mark error AND revert local fields to previous values (avoid silent divergence)
        mr["title"] = old_title
        mr["description"] = old_desc
        mr["status"] = "error"  # syncing->error is legal
        mr["updated_at"] = now
        mrs[mr_idx] = mr
        _save("merge_requests.json", mrs)

        for c in conns:
            if isinstance(c, dict) and c.get("id") == conn.get("id"):
                c["updated_at"] = now
                c["last_error"] = (last_err or "GitLab update failed")[:500]
                break
        _save("gitlab_connections.json", conns)

        _log(conn.get("id"), "error", "UNAUTHORIZED" if isinstance(last_err, str) and last_err.startswith("401") else "CONFLICT",
             "GitLab update failed; local changes reverted.", {"project_id": project_id, "merge_request_id": mr.get("id"), "rate_bucket": bucket, "rate_error": last_err})
        return _err("CONFLICT", "GitLab update failed; local changes reverted.", project_id=project_id, merge_request_id=mr.get("id"))

    # success path: syncing->active
    mr["status"] = "active"
    mr["updated_at"] = now
    mrs[mr_idx] = mr
    _save("merge_requests.json", mrs)

    for c in conns:
        if isinstance(c, dict) and c.get("id") == conn.get("id"):
            c["updated_at"] = now
            c["last_error"] = None
            break
    _save("gitlab_connections.json", conns)

    _log(conn.get("id"), "ok", None, None, {"project_id": project_id, "merge_request_id": mr.get("id"), "rate_bucket": bucket})
    return {"merge_request": mr, "connection_id": conn.get("id"), "project_id": project_id}

def retry_note_delivery(note_id, **_extra):
    import json, os, datetime, re, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0207000" if __import__("os").path.isdir("./environment_mix/0207000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _new_log_id():
        return "glrl_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S") + ("%06d" % random.randint(0, 999999))

    def _log(connection_id, status_s, error_code=None, error_message=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _new_log_id(),
            "endpoint": "retry_note_delivery",
            "tool": "retry_note_delivery",
            "connection_id": connection_id,
            "status": status_s,
            "error_code": error_code,
            "error_message": (error_message[:500] if isinstance(error_message, str) else error_message),
            "meta": meta or {},
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now,
            "ts": now,
        })
        _save("request_logs.json", logs)

    # Rate limiting: enforce per connection bucket max requests/minute
    # Configured maximum requests/minute (reasonable default for this offline backend)
    MAX_RPM = 60

    def _rate_bucket(conn):
        return conn.get("rate_limit_bucket") or conn.get("id")

    def _count_recent_bucket_calls(bucket, seconds=60):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return 0
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=seconds)
        c = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            meta = r.get("meta") or {}
            if not isinstance(meta, dict) or meta.get("rate_bucket") != bucket:
                continue
            ts = r.get("created_at") or r.get("ts")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= cutoff:
                c += 1
        return c

    # validate
    if not isinstance(note_id, str) or not re.match(r"^gln_[0-9A-Z]+$", note_id):
        _log(None, "error", "VALIDATION_ERROR", "Invalid note_id format.", {"field": "note_id"})
        return _err("VALIDATION_ERROR", "note_id is invalid; expected ^gln_[0-9A-Z]+$.", field="note_id")

    notes = _load("notes.json")
    if not isinstance(notes, list):
        notes = []

    note = None
    note_idx = None
    for i, n in enumerate(notes):
        if isinstance(n, dict) and n.get("id") == note_id:
            note = n
            note_idx = i
            break
    if not note:
        _log(None, "error", "NOT_FOUND", "Note not found.", {"note_id": note_id})
        return _err("NOT_FOUND", "Note not found.", note_id=note_id)

    if note.get("status") == "deleted":
        _log(None, "error", "CONFLICT", "Cannot retry a deleted note.", {"note_id": note_id})
        return _err("CONFLICT", "Cannot retry delivery of a deleted note.", note_id=note_id)

    project_id = note.get("project_id")
    if not isinstance(project_id, str):
        _log(None, "error", "CONFLICT", "Note is missing project_id.", {"note_id": note_id})
        return _err("CONFLICT", "Note is missing project_id; cannot resolve connection.", note_id=note_id)

    projects = _load("projects.json")
    if not isinstance(projects, list):
        projects = []
    proj = None
    for p in projects:
        if isinstance(p, dict) and p.get("id") == project_id:
            proj = p
            break
    if not proj:
        _log(None, "error", "NOT_FOUND", "Project for note not found.", {"note_id": note_id, "project_id": project_id})
        return _err("NOT_FOUND", "Project for note not found.", note_id=note_id, project_id=project_id)

    conns = _load("gitlab_connections.json")
    if not isinstance(conns, list):
        conns = []
    conn = None
    for c in conns:
        if isinstance(c, dict) and c.get("id") == proj.get("connection_id") and c.get("status") == "active":
            conn = c
            break
    if conn is None:
        for c in conns:
            if isinstance(c, dict) and c.get("id") == proj.get("connection_id") and c.get("status") in ("active", "disabled"):
                conn = c
                break
    if conn is None:
        _log(None, "error", "UNAUTHORIZED", "No usable GitLab connection for note's project.", {"note_id": note_id, "project_id": project_id})
        return _err("UNAUTHORIZED", "No usable GitLab connection for note's project.", note_id=note_id, project_id=project_id)

    # Enforce rate limit before mutating note state (except connection updated_at allowed by business rule)
    bucket = _rate_bucket(conn)
    recent = _count_recent_bucket_calls(bucket, 60)
    if recent >= MAX_RPM:
        # Allowed mutation: bump connection updated_at only
        now_iso = now
        for c in conns:
            if isinstance(c, dict) and c.get("id") == conn.get("id"):
                c["updated_at"] = now_iso
                break
        _save("gitlab_connections.json", conns)
        _log(conn.get("id"), "error", "RATE_LIMIT", "GitLab API rate limit exceeded for connection.", {"rate_bucket": bucket, "recent_calls_60s": recent})
        return _err("RATE_LIMIT", "Rate limit exceeded for this GitLab connection; retry later.", retry_after_seconds=60)

    # Lifecycle transitions
    cur_status = note.get("status")
    if cur_status not in ("failed", "pending_create", "synced"):
        _log(conn.get("id"), "error", "INVALID_TRANSITION", "Cannot retry note from this status.", {"note_id": note_id, "status": cur_status})
        return _err("INVALID_TRANSITION", "Cannot retry note delivery from current status.", note_id=note_id, status=cur_status)

    # If already synced, idempotently return it (no effect would be a mock; but real APIs commonly treat retry as idempotent)
    if cur_status == "synced":
        _log(conn.get("id"), "ok", meta={"note_id": note_id, "idempotent": True, "rate_bucket": bucket})
        return {"note": note}

    # Move to pending_create (failed -> pending_create allowed, pending_create -> pending_create idempotent)
    if cur_status == "failed":
        note["status"] = "pending_create"
        note["updated_at"] = now

    # "Attempt GitLab creation": offline backend simulates delivery success if connection is active; failure if disabled/revoked
    delivery_ok = (conn.get("status") == "active")

    if delivery_ok:
        # Success: transition pending_create -> synced, fill gitlab_note_id/gitlab_created_at if missing
        note["status"] = "synced"
        if note.get("gitlab_note_id") is None:
            note["gitlab_note_id"] = int(random.randint(1, 2_000_000_000))
        if note.get("gitlab_created_at") is None:
            note["gitlab_created_at"] = now
        note["updated_at"] = now
        notes[note_idx] = note
        _save("notes.json", notes)
        _log(conn.get("id"), "ok", meta={"note_id": note_id, "rate_bucket": bucket, "delivered": True})
        return {"note": note}

    # Failure path: pending_create -> failed
    note["status"] = "failed"
    note["updated_at"] = now
    notes[note_idx] = note
    _save("notes.json", notes)

    # Store error in application log file
    app_logs = _load("application_logs.json")
    if not isinstance(app_logs, list):
        app_logs = []
    app_logs.append({
        "id": "glal_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S") + ("%06d" % random.randint(0, 999999)),
        "kind": "gitlab_note_delivery",
        "note_id": note_id,
        "project_id": project_id,
        "connection_id": conn.get("id"),
        "message": "GitLab delivery failed: connection is not active.",
        "created_at": now
    })
    _save("application_logs.json", app_logs)

    _log(conn.get("id"), "error", "CONFLICT", "GitLab delivery failed (connection not active).", {"note_id": note_id, "rate_bucket": bucket})
    return _err("CONFLICT", "GitLab delivery failed; connection is not active.", note_id=note_id, connection_status=conn.get("status"))
